    capa.push_back(std::make_unique<ReLU>());
    capa.push_back(std::make_unique<Sigmoide>());

    std::cout << std::fixed << std::setprecision(3);
    for (const auto& act : capa) {
        std::cout << act->nombre() << "(-2) = " << act->aplicar(-2.0) << '\n';
