class Transformador {
public:
    virtual ~Transformador() = default;
    virtual double aplicar(double x) const = 0;
};

class Escalar : public Transformador {
public:
    explicit Escalar(double factor) : factor_(factor) {}
    double aplicar(double x) const override { return x * factor_; }

private:
    double factor_;
};

class Recortar : public Transformador {
public:
    explicit Recortar(double limite) : limite_(limite) {}
    double aplicar(double x) const override { return std::min(x, limite_); }

private:
    double limite_;
};

class Pipeline {
public:
    void agregar(std::unique_ptr<Transformador> paso) {
        pasos_.push_back(std::move(paso));
    }

    double ejecutar(double x) const {
        for (const auto& paso : pasos_) {
            x = paso->aplicar(x);
        }
        return x;
    }

private:
    std::vector<std::unique_ptr<Transformador>> pasos_;
};

int main() {
    Pipeline p;
    p.agregar(std::make_unique<Escalar>(2.0));
    p.agregar(std::make_unique<Recortar>(5.0));
    std::cout << p.ejecutar(4.0) << '\n';
    return 0;
}

