#include <algorithm>
#include <iomanip>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

class Figura {
public:
    virtual ~Figura() = default;
    virtual double area() const = 0;
    virtual std::string nombre() const = 0;
};

class Circulo : public Figura {
public:
    explicit Circulo(double radio) : radio_(radio) {}
    double area() const override { return 3.141592653589793 * radio_ * radio_; }
    std::string nombre() const override { return "circulo"; }

private:
    double radio_;
};

class Rectangulo : public Figura {
public:
    Rectangulo(double ancho, double alto) : ancho_(ancho), alto_(alto) {}
    double area() const override { return ancho_ * alto_; }
    std::string nombre() const override { return "rectangulo"; }

private:
    double ancho_;
    double alto_;
};

class Triangulo : public Figura {
public:
    Triangulo(double base, double altura) : base_(base), altura_(altura) {}
    double area() const override { return base_ * altura_ / 2.0; }
    std::string nombre() const override { return "triangulo"; }

private:
    double base_;
    double altura_;
};

int main() {
    std::vector<std::unique_ptr<Figura>> figuras;
    figuras.push_back(std::make_unique<Circulo>(1.0));
    figuras.push_back(std::make_unique<Rectangulo>(2.0, 3.0));
    figuras.push_back(std::make_unique<Triangulo>(4.0, 5.0));

    std::cout << std::fixed << std::setprecision(2);
    double total = 0.0;
    for (const auto& f : figuras) {
        std::cout << f->nombre() << ": " << f->area() << '\n';
        total += f->area();
    }

    const auto mayor = std::max_element(
        figuras.begin(), figuras.end(),
        [](const std::unique_ptr<Figura>& a, const std::unique_ptr<Figura>& b) {
            return a->area() < b->area();
        });

    std::cout << "total: " << total << '\n';
    std::cout << "mayor: " << (*mayor)->nombre() << '\n';
    return 0;
}

#include <cmath>
#include <iomanip>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

class Metrica {
public:
    virtual ~Metrica() = default;
    virtual double calcular(const std::vector<double>& real,
                            const std::vector<double>& pred) const = 0;
    virtual std::string nombre() const = 0;
};

class MAE : public Metrica {
public:
    double calcular(const std::vector<double>& real,
                    const std::vector<double>& pred) const override {
        double suma = 0.0;
        for (std::size_t i = 0; i < real.size(); ++i) {
            suma += std::abs(real[i] - pred[i]);
        }
        return suma / static_cast<double>(real.size());
    }
    std::string nombre() const override { return "MAE"; }
};

class RMSE : public Metrica {
public:
    double calcular(const std::vector<double>& real,
                    const std::vector<double>& pred) const override {
        double suma = 0.0;
        for (std::size_t i = 0; i < real.size(); ++i) {
            const double error = real[i] - pred[i];
            suma += error * error;
        }
        return std::sqrt(suma / static_cast<double>(real.size()));
    }
    std::string nombre() const override { return "RMSE"; }
};

int main() {
    const std::vector<double> real{3.0, 5.0};
    const std::vector<double> pred{2.0, 7.0};

    std::vector<std::unique_ptr<Metrica>> metricas;
    metricas.push_back(std::make_unique<MAE>());
    metricas.push_back(std::make_unique<RMSE>());

    std::cout << std::fixed << std::setprecision(2);
    for (const auto& m : metricas) {
        std::cout << m->nombre() << ": " << m->calcular(real, pred) << '\n';
    }
    return 0;
}

